seq = open("region.fasta").read().split("\n", 1)[1].replace("\n", "").strip()

stops = ("TAA","TAG","TGA")

def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_orfs(s,minlen_aa=50):
    res=[]
    L=len(s)
    for name,ss in (("+",s),("-",revcomp(s))):
        for frame in range(3):
            i=frame
            while i+2<L:
                if ss[i:i+3]=="ATG":
                    j=i
                    aa=0
                    found_stop=None
                    while j+2<L:
                        c=ss[j:j+3]
                        if c in stops:
                            found_stop=j+3
                            break
                        j+=3
                        aa+=1
                    if found_stop is None:
                        found_stop=L
                        partial=True
                    else:
                        partial=False
                    if aa>=minlen_aa:
                        if name=="+":
                            res.append((name,frame, i+1, found_stop, aa, partial))
                        else:
                            res.append((name,frame, L-found_stop+1, L-i, aa, partial))
                    i=i+3
                else:
                    i+=3
    return res

res = find_orfs(seq, minlen_aa=40)
res.sort(key=lambda r:-r[4])
for r in res[:20]:
    p = " (partial, runs off edge)" if r[5] else ""
    print(f"strand {r[0]} frame {r[1]}+1? coords {r[2]}-{r[3]}  length {r[4]} aa{p}")
print("total ORFs >=40 aa:", len(res))
