# CpG islands
best=[]
n=len(seq)
for start in range(0, n-200, 50):
    w=seq[start:start+200]
    gc=(w.count("G")+w.count("C"))/len(w)*100
    obs=w.count("CG"); exp=w.count("C")*w.count("G")/len(w)
    oe=obs/exp if exp else 0
    if gc>50 and oe>0.6:
        best.append((start+1, start+200, round(gc,1), round(oe,2), obs))
def merge(a):
    out=[]
    for s in a:
        if out and s[0]<=out[-1][1]+1:
            out[-1][1]=max(out[-1][1],s[1])
        else: out.append([s[0],s[1]])
    return out
print("exceeding 200bp windows:", merge(best) if merge(best) else "NONE")
